describe('Record Created and Last Modified Dates', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should display created and last modified dates on a record', () => {
    // Intercept the API call to fetch records
    cy.intercept('GET', '/api/records').as('getRecords');
    cy.get('[data-testid="load-records-button"]').click();
    cy.wait('@getRecords');

    // Verify the record list is displayed
    cy.get('[data-testid="record-list"]').should('be.visible');
    cy.get('[data-testid="record-item"]').should('have.length.greaterThan', 0);

    // Verify the created date is displayed for the first record
    cy.get('[data-testid="record-item:first"]').within(() => {
      cy.get('[data-testid="created-date"]').should('be.visible');
      cy.get('[data-testid="created-date"]').should('contain', 'Created:');
    });

    // Verify the last modified date is displayed for the first record
    cy.get('[data-testid="record-item:first"]').within(() => {
      cy.get('[data-testid="last-modified-date"]').should('be.visible');
      cy.get('[data-testid="last-modified-date"]').should('contain', 'Last Modified:');
    });

    // Verify both dates are present and formatted correctly
    cy.get('[data-testid="record-item:first"]').within(() => {
      cy.get('[data-testid="created-date"]').should('have.length', 1);
      cy.get('[data-testid="last-modified-date"]').should('have.length', 1);
    });
  });

  it('should handle missing dates gracefully when record is created without modification', () => {
    // Intercept the API call with a record that has no last modified date
    cy.intercept('GET', '/api/records', {
      statusCode: 200,
      body: [
        {
          id: 1,
          name: 'New Record',
          created_at: '2023-10-26T10:00:00Z',
          last_modified_at: null
        }
      ]
    }).as('getRecordsWithNullModifiedDate');
    cy.get('[data-testid="load-records-button"]').click();
    cy.wait('@getRecordsWithNullModifiedDate');

    // Verify the record is displayed
    cy.get('[data-testid="record-item"]').should('have.length', 1);

    // Verify created date is displayed
    cy.get('[data-testid="record-item"]').within(() => {
      cy.get('[data-testid="created-date"]').should('be.visible');
      cy.get('[data-testid="created-date"]').should('contain', 'Created:');
    });

    // Verify last modified date displays a placeholder or "N/A" when null
    cy.get('[data-testid="record-item"]').within(() => {
      cy.get('[data-testid="last-modified-date"]').should('be.visible');
      cy.get('[data-testid="last-modified-date"]').should('contain', 'Never modified');
    });

    // Verify the record still functions normally
    cy.get('[data-testid="record-item"]').should('be.visible');
  });
});
